#!/usr/bin/env bash
# Print the Homebrew formula for one bridge release: homebrew-formula.sh VERSION SHA256SUMS
set -euo pipefail
version=$1 sums=$2 base="https://github.com/gremia-tech/agent-remote-bridge/releases/download/server-v$1"
sha() { awk -v f="agent-remote-bridge-$version-$1.zip" '$2==f{print $1}' "$sums" | grep -E '^[0-9a-f]{64}$'; }
cat <<RUBY
# Generated by gremia-tech/agent-remote-bridge on each release; do not edit by hand.
class AgentRemoteBridge < Formula
  desc "Bridge for the AI Agent Remote app: watch and control coding agents from your phone"
  homepage "https://github.com/gremia-tech/agent-remote-bridge"
  version "$version"
  license "Apache-2.0"

  on_macos do
    on_arm do
      url "$base/agent-remote-bridge-$version-macos-arm64.zip"
      sha256 "$(sha macos-arm64)"
    end
    on_intel do
      url "$base/agent-remote-bridge-$version-macos-x64.zip"
      sha256 "$(sha macos-x64)"
    end
  end
  on_linux do
    on_arm do
      url "$base/agent-remote-bridge-$version-linux-arm64.zip"
      sha256 "$(sha linux-arm64)"
    end
    on_intel do
      url "$base/agent-remote-bridge-$version-linux-x64.zip"
      sha256 "$(sha linux-x64)"
    end
  end

  def install
    libexec.install Dir["*"]
    bin.install_symlink libexec/"herdr-remote"
  end

  def caveats
    "Run \`herdr-remote up\` and pair from the AI Agent Remote app on the same Wi-Fi."
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/herdr-remote --help")
  end
end
RUBY
